package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.zip.GZIPOutputStream;
import org.jlinalg.genetics.MinimacReferenceBlocks;
import org.jlinalg.genetics.VcfCsiIndex;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class MinimacVcfTest {
    @TempDir Path directory;
    private static final MinimacVcf.Limits LIMITS = new MinimacVcf.Limits(100,100,10000,1048576,1048576,8192,1048576,1000);
    private static final String ID_HEADER = "contig\tcolumn_id\tcolumn_copy\tperson_id\tperson_copy\n";
    private static final String IDENTITIES = ID_HEADER+"1\tA\t1\tpersonA\t1\n1\tA\t2\tpersonA\t2\n1\tB\t1\tpersonB\t1\n1\tB\t2\tpersonB\t2\n";
    private static final String VCF = "##fileformat=VCFv4.2\n##INFO=<ID=AC,Number=A,Type=Integer,Description=\"Original annotation\">\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tA\tB\n"
            +"1\t10\tv1\tA\tG\t.\tPASS\tAC=2\tGT:DP\t0|1:20\t1|0:25\n"
            +"1\t20\tv2\tC\tT\t.\tPASS\t.\tDP:GT\t5:1|1\t7:0|1\n";
    private Path file(String contents) throws IOException {Path p=Files.createTempFile(directory,"input-",".txt");Files.writeString(p,contents);return p;}
    private MinimacVcf.Identity identity(String contents) throws IOException {return MinimacVcf.identity(file(contents),LIMITS);}
    private MinimacVcf.Summary read(String contents) throws IOException {return MinimacVcf.read(file(contents),MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{});}
    private void reject(String contents) {assertThrows(IOException.class,()->read(contents));}
    @Test void completeReferenceKeepsColumnCopyOrderAndReportsAllCounts() throws Exception {
        var rows=new ArrayList<MinimacVcf.Row>();var s=MinimacVcf.read(file(VCF),MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->rows.add(row));
        assertEquals(List.of("A","B"),s.columns());assertEquals(List.of(2,2),s.contigs().get(0).columnPloidies());assertEquals(2,s.input().variants());assertEquals(4,s.input().genotypeCells());assertEquals(8,s.input().haplotypeCopies());assertEquals(8,s.input().observedCopies());assertEquals(0,s.input().missingCopies());assertEquals(s.input(),s.selected());assertEquals(List.of(0,1),rows.get(0).calls().get(0).alleles());assertEquals(List.of(1,0),rows.get(0).calls().get(1).alleles());assertEquals("1|1",rows.get(1).calls().get(0).original());
    }
    @Test void equivalentMvcfHasEqualMatrixAndSampleIdentityFingerprints() throws Exception {
        String text="##fileformat=VCFv4.2\n##subfileformat=MVCFv3.0\n##phasing=full\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tA\tB\n1\t10\t.\tA\t<BLOCK>\t.\t.\tEND=20;VARIANTS=2;REPS=4\tUHM\t0,1\t2,3\n1\t10\tv1\tA\tG\t.\t.\tAC=2;AN=4;UHA=0,1,1,0\n1\t20\tv2\tC\tT\t.\t.\tAC=3;AN=4;UHA=1,1,0,1\n";
        var a=read(VCF);var b=MinimacReferenceBlocks.audit(file(text),MinimacReferenceBlocks.BoundaryPolicy.REJECT_DUPLICATES);assertEquals(b.orderedHaplotypeMatrixSha256(),a.input().orderedMatrixSha256());assertEquals(b.identityAndPhaseSha256(),a.input().identityPhaseSha256());
    }
    @Test void phaseSwapChangesMatrixWithoutInventingNewAlleles() throws Exception {assertNotEquals(read(VCF).input().orderedMatrixSha256(),read(VCF.replace("0|1:20","1|0:20")).input().orderedMatrixSha256());}
    @Test void markerIdentityAndMatrixHashesHaveSeparateScopes() throws Exception {var a=read(VCF);var b=read(VCF.replace("\tv1\t","\tnew-id\t"));assertEquals(a.input().orderedMatrixSha256(),b.input().orderedMatrixSha256());assertNotEquals(a.input().identityPhaseSha256(),b.input().identityPhaseSha256());}
    @Test void explicitGtOnlyStagingPreservesGenotypesAndProducesACompleteNativeIndex() throws Exception {
        Path input=file(VCF),staged=directory.resolve("staged.vcf.gz");byte[] before=Files.readAllBytes(input);
        var a=MinimacVcf.read(input,MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,staged,row->MinimacVcf.Selection.retain(),(row,selection)->{});
        var b=MinimacVcf.read(staged,MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{});
        assertEquals(a.input(),b.input());assertArrayEquals(before,Files.readAllBytes(input));assertTrue(b.gzip());assertEquals(1,VcfCsiIndex.create(staged,directory.resolve("staged.vcf.gz.csi")).contigs());
        try(var stream=new java.util.zip.GZIPInputStream(Files.newInputStream(staged))){String text=new String(stream.readAllBytes(),StandardCharsets.UTF_8);assertFalse(text.contains("AC=2"));assertFalse(text.contains("GT:DP"));assertTrue(text.contains("\t.\t.\t.\tGT\t0|1\t1|0\n"));}
    }
    @Test void stagedDestinationIsNeverOverwritten() throws Exception {Path p=directory.resolve("existing.vcf.gz");Files.writeString(p,"sentinel");assertThrows(IOException.class,()->MinimacVcf.read(file(VCF),MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,p,row->MinimacVcf.Selection.retain(),(row,selection)->{}));assertEquals("sentinel",Files.readString(p));}
    @Test void exclusionsAreExplicitAndRetainedInInputCountsAndTheVisitor() throws Exception {
        var events=new ArrayList<String>();Path staged=directory.resolve("selected.vcf.gz");
        var s=MinimacVcf.read(file(VCF),MinimacVcf.Role.TARGET,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,staged,row->row.position()==10?new MinimacVcf.Selection(false,"EXPLICIT_TARGET_ONLY_EXCLUSION"):MinimacVcf.Selection.retain(),(row,selection)->events.add(row.id()+":"+selection.reason()));
        assertEquals(2,s.input().variants());assertEquals(1,s.selected().variants());assertEquals(1,s.excludedVariants());assertEquals(4,s.selected().haplotypeCopies());assertEquals(List.of("v1:EXPLICIT_TARGET_ONLY_EXCLUSION","v2:RETAINED"),events);
        assertEquals(1,MinimacVcf.read(staged,MinimacVcf.Role.TARGET,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{}).input().variants());
    }
    @Test void referenceMarkersCannotBeDroppedByAnIntakeSelector() throws Exception {assertThrows(IOException.class,()->MinimacVcf.read(file(VCF),MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->new MinimacVcf.Selection(false,"unapproved-reference-filter"),(row,selection)->{}));}
    @Test void emptyTargetSelectionRemainsExplicitAndCannotProduceAnAdmittedCsi() throws Exception {Path staged=directory.resolve("empty.vcf.gz");var s=MinimacVcf.read(file(VCF),MinimacVcf.Role.TARGET,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,staged,row->new MinimacVcf.Selection(false,"EXPLICIT_TARGET_ONLY_EXCLUSION"),(row,selection)->{});assertEquals(0,s.selected().variants());assertThrows(IOException.class,()->VcfCsiIndex.create(staged,directory.resolve("empty.csi")));}
    @Test void referenceMissingCallsAreRejectedForEveryMissingPolicy() throws Exception {for(var p:MinimacVcf.MissingPolicy.values())assertThrows(IOException.class,()->MinimacVcf.read(file(VCF.replace("0|1:20",".|.:20")),MinimacVcf.Role.REFERENCE,identity(IDENTITIES),p,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{}));}
    @Test void targetMissingCopiesAndPartialPhaseAreCountedWithoutObservedCallChanges() throws Exception {
        var rows=new ArrayList<MinimacVcf.Row>();var s=MinimacVcf.read(file(VCF.replace("0|1:20",".|.:20").replace("1|0:25","1|.:25")),MinimacVcf.Role.TARGET,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->rows.add(row));assertEquals(3,s.input().missingCopies());assertEquals(5,s.input().observedCopies());assertEquals(1,s.input().fullyMissingCalls());assertEquals(1,s.input().partiallyMissingCalls());assertEquals(List.of(1,-1),rows.get(0).calls().get(1).alleles());assertEquals(0,s.input().stagedGtRepresentationChanges());
    }
    @Test void missingDiploidDotRequiresExplicitDeclaredPloidyPolicy() throws Exception {
        String text=VCF.replace("0|1:20",".:20");assertThrows(IOException.class,()->MinimacVcf.read(file(text),MinimacVcf.Role.TARGET,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{}));
        var calls=new ArrayList<MinimacVcf.Call>();var s=MinimacVcf.read(file(text),MinimacVcf.Role.TARGET,identity(IDENTITIES),MinimacVcf.MissingPolicy.ALLOW_FULL_MISSING_WITH_DECLARED_PLOIDY,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->calls.add(row.calls().get(0)));assertEquals(".|.",calls.get(0).staged());assertEquals(".",calls.get(0).original());assertEquals(1,s.input().missingRepresentationChanges());assertEquals(2,s.input().missingCopies());
    }
    @Test void onlyExplicitHomozygotePolicyAcceptsUnphasedIdenticalAlleles() throws Exception {
        String text=VCF.replace("0|1:20","0/0:20");reject(text);var s=MinimacVcf.read(file(text),MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.ALLOW_UNPHASED_HOMOZYGOTES,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{});assertEquals(1,s.input().homozygousPhaseRepresentationChanges());assertEquals(1,s.input().stagedGtRepresentationChanges());
        for(String gt:List.of("0/1","0/.","./0"))assertThrows(IOException.class,()->MinimacVcf.read(file(VCF.replace("0|1:20",gt+":20")),MinimacVcf.Role.TARGET,identity(IDENTITIES),MinimacVcf.MissingPolicy.ALLOW_FULL_MISSING_WITH_DECLARED_PLOIDY,MinimacVcf.PhasePolicy.ALLOW_UNPHASED_HOMOZYGOTES,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{}));
    }
    @Test void fullyMissingSlashCanBeRepresentedOnlyUnderItsOwnExplicitPolicy() throws Exception {var s=MinimacVcf.read(file(VCF.replace("0|1:20","./.:20")),MinimacVcf.Role.TARGET,identity(IDENTITIES),MinimacVcf.MissingPolicy.ALLOW_FULL_MISSING_WITH_DECLARED_PLOIDY,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{});assertEquals(1,s.input().missingRepresentationChanges());assertEquals(0,s.input().homozygousPhaseRepresentationChanges());}
    @Test void genotypeAlleleIntegersAreCanonicalizedWithoutChangingTheirIndices() throws Exception {var s=MinimacVcf.read(file(VCF.replace("0|1:20","00|01:20")),MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{if(row.position()==10)assertEquals("0|1",row.calls().get(0).staged());});assertEquals(read(VCF).input().orderedMatrixSha256(),s.input().orderedMatrixSha256());assertEquals(1,s.input().stagedGtRepresentationChanges());}
    @Test void explicitPerContigPloidiesPermitHaploidAndDiploidCallsWithoutSexInference() throws Exception {String ids=IDENTITIES+"X\tA\t1\tpersonA\t1\nX\tB\t1\tpersonB\t1\nX\tB\t2\tpersonB\t2\n";var s=MinimacVcf.read(file(VCF+"X\t50\tx1\tG\tA\t.\t.\t.\tGT\t1\t0|1\n"),MinimacVcf.Role.REFERENCE,identity(ids),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{});assertEquals(List.of(1,2),s.contigs().get(1).columnPloidies());assertEquals(11,s.input().haplotypeCopies());}
    @Test void undeclaredOrChangedPloidyIsNotFilledIn() {reject(VCF.replace("0|1:20","0:20"));reject(VCF.replace("0|1:20","0|1|0:20"));reject(VCF.replace("0|1:20","|1:20"));reject(VCF.replace("0|1:20","2|1:20"));}
    @Test void exactLedgerJoinRejectsMissingExtraOrReusedPhysicalCopies() throws Exception {
        for(String ids:List.of(IDENTITIES.replace("column_id","wrong"),IDENTITIES+"1\tA\t1\tpersonA\t1\n",IDENTITIES.replace("1\tB\t1\tpersonB\t1","1\tB\t1\tpersonA\t1"),IDENTITIES.replace("1\tA\t1\tpersonA\t1\n","")))assertThrows(IOException.class,()->identity(ids));
        for(String ids:List.of(IDENTITIES.replace("\tB\t","\tC\t"),IDENTITIES+"2\tA\t1\tp2\t1\n2\tB\t1\tp3\t1\n"))assertThrows(IOException.class,()->MinimacVcf.read(file(VCF),MinimacVcf.Role.REFERENCE,identity(ids),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{}));
    }
    @Test void ledgerOrderAndHaplotypeLookingNamesNeverInferPersonPairs() throws Exception {String ids=ID_HEADER+"1\tB\t2\tq\t2\n1\tA\t2\tp\t2\n1\tB\t1\tq\t1\n1\tA\t1\tp\t1\n";var a=identity(ids);assertEquals(List.of(new MinimacVcf.Copy("p",1),new MinimacVcf.Copy("p",2)),a.copies("1","A"));var s=MinimacVcf.read(file(VCF.replace("FORMAT\tA\tB","FORMAT\tweird_HAP_2\tweird_HAP_1")),MinimacVcf.Role.REFERENCE,identity(IDENTITIES.replace("\tA\t","\tweird_HAP_2\t").replace("\tB\t","\tweird_HAP_1\t")),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{});assertEquals(List.of(2,2),s.contigs().get(0).columnPloidies());}
    @Test void duplicateSampleMarkerAndFormatKeysFail() {reject(VCF.replace("FORMAT\tA\tB","FORMAT\tA\tA"));reject(VCF.replace("1\t20\tv2\tC\tT","1\t10\tv2\tA\tG"));reject(VCF.replace("GT:DP","GT:GT"));reject(VCF.replace("GT:DP","PL:DP"));reject(VCF.replace("0|1:20","0|1:20:extra"));}
    @Test void unsortedPositionsContigReentryAndBlankRowsFail() {reject(VCF.replace("1\t20\tv2","1\t9\tv2"));reject(VCF+"\n");reject(VCF+"2\t5\tx\tG\tA\t.\t.\t.\tGT\t0|1\t0|1\n");}
    @Test void unsupportedAllelesAndHeadersAreNeverNormalized() {for(String alt:List.of(".","G,T","<DEL>","*"))reject(VCF.replace("\tv1\tA\tG\t","\tv1\tA\t"+alt+"\t"));reject(VCF.replace("\tv1\tA\tG\t","\tv1\tA\tA\t"));reject(VCF.replace("VCFv4.2","BCFv2.2"));reject("##fileformat=VCFv4.2\n"+VCF);reject(VCF.replace("#CHROM\tPOS","#CHROM\tPOSITION"));}
    @Test void gzipCrLfAndAbsentFinalLfPreserveDecodedFingerprints() throws Exception {Path p=directory.resolve("crlf.gz");try(var out=new GZIPOutputStream(Files.newOutputStream(p))){out.write(VCF.replace("\n","\r\n").stripTrailing().getBytes(StandardCharsets.UTF_8));}var s=MinimacVcf.read(p,MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{});assertTrue(s.gzip());assertFalse(s.finalLineHasLf());assertEquals(4,s.crlfLines());assertEquals(read(VCF).input(),s.input());}
    @Test void invalidUtf8AndControlCharactersFailWithReleasedInputHandles() throws Exception {Path p=directory.resolve("invalid.txt");Files.write(p,new byte[]{(byte)255});assertThrows(IOException.class,()->MinimacVcf.read(p,MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{}));Files.delete(p);reject(VCF.replace("\tPASS\t","\tPA\u0001SS\t"));Path c=file(VCF.replace("\tv1\t","\tbad\u0000id\t"));assertTrue(assertThrows(IOException.class,()->MinimacVcf.read(c,MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->{})).getMessage().contains("line 4:"));}
    @Test void independentResourceBoundsFailBeforeAnAnalysisCanBeAdmitted() throws Exception {
        var choices=List.of(new MinimacVcf.Limits(1,100,1000,1048576,1048576,8192,1048576,1000),new MinimacVcf.Limits(100,1,1000,1048576,1048576,8192,1048576,1000),new MinimacVcf.Limits(100,100,3,1048576,1048576,8192,1048576,1000),new MinimacVcf.Limits(100,100,1000,32,1048576,8192,1048576,1000),new MinimacVcf.Limits(100,100,1000,1048576,80,8192,1048576,1000),new MinimacVcf.Limits(100,100,1000,1048576,1048576,64,1048576,1000),new MinimacVcf.Limits(100,100,1000,1048576,1048576,8192,16,1000));
        var ids=identity(IDENTITIES);for(var limits:choices){Path out=directory.resolve("bounded-"+System.nanoTime()+".vcf.gz");assertThrows(IOException.class,()->MinimacVcf.read(file(VCF),MinimacVcf.Role.REFERENCE,ids,MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,limits,out,row->MinimacVcf.Selection.retain(),(row,selection)->{}));if(Files.exists(out))Files.delete(out);}
        assertThrows(IOException.class,()->MinimacVcf.identity(file(IDENTITIES),new MinimacVcf.Limits(100,100,1000,1048576,1048576,8192,1048576,3)));
    }
    @Test void consumerFailureRetainsItsCauseAndReleasesInputAndPartialStage() throws Exception {Path in=file(VCF),out=directory.resolve("partial.vcf.gz");byte[] before=Files.readAllBytes(in);IOException sentinel=new IOException("downstream failed");assertSame(sentinel,assertThrows(IOException.class,()->MinimacVcf.read(in,MinimacVcf.Role.REFERENCE,identity(IDENTITIES),MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,out,row->MinimacVcf.Selection.retain(),(row,selection)->{throw sentinel;})));assertArrayEquals(before,Files.readAllBytes(in));Files.delete(in);Files.delete(out);}
    @Test void returnedIdentitiesRowsAndInventoriesAreImmutable() throws Exception {var ids=identity(IDENTITIES);assertThrows(UnsupportedOperationException.class,()->ids.contigs().clear());assertThrows(UnsupportedOperationException.class,()->ids.copies("1","A").clear());var s=MinimacVcf.read(file(VCF),MinimacVcf.Role.REFERENCE,ids,MinimacVcf.MissingPolicy.EXACT_PHASED,MinimacVcf.PhasePolicy.REQUIRE_PIPE,LIMITS,null,row->MinimacVcf.Selection.retain(),(row,selection)->assertThrows(UnsupportedOperationException.class,()->row.calls().get(0).alleles().clear()));assertThrows(UnsupportedOperationException.class,()->s.columns().clear());assertThrows(UnsupportedOperationException.class,()->s.contigs().get(0).columnPloidies().clear());}
    @Test void integerRangeEmptyInputAndMissingGtFailWithoutInventedCalls() {reject("");reject(VCF.substring(0,VCF.indexOf("1\t10\t")));reject(VCF.replace("1\t10\t","1\t2147483648\t"));reject(VCF.replace("1\t10\t","1\t0\t"));reject(VCF.replace("0|1:20",":20"));reject(VCF.replace("5:1|1","5"));}
}

